package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.workflow.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.assertEquals;
class LoopNodeExecutorTest {@Test void failsExplicitlyWhenIterationLimitIsExceeded(){ObjectMapper mapper=new ObjectMapper();Map<String,Object> variables=new HashMap<>();variables.put("loop.loop.iteration",2);WorkflowNodeDefinition node=NodeExecutorTestSupport.node("loop",WorkflowNodeType.LOOP,"{\"maxIterations\":2,\"terminationCondition\":{\"eq\":[1,2]}}");List<WorkflowEdgeDefinition> edges=Arrays.asList(NodeExecutorTestSupport.edge("loop","body",null,1,"body"),NodeExecutorTestSupport.edge("loop","exit",null,0,"exit"));NodeExecutionResult result=new LoopNodeExecutor(mapper,new ConditionDslEvaluator(mapper)).execute(NodeExecutorTestSupport.context(node,variables,edges));assertEquals("LOOP_ITERATION_LIMIT_EXCEEDED",result.getErrorCode());}}
